-- =====================================================================
-- 02_sync_templates.sql — bring email_templates in line with the canonical catalog
--
-- Run AFTER 01_preflight.sql on the same connection/session, and BEFORE 03_verify.sql.
--
-- GENERATED, DO NOT HAND-EDIT. The 31 VALUES rows below are the CANONICAL SEED's own values, read
-- back out of a database freshly imported from
--   docs/database/scripts/PEMS_FULL_VS_31_07_NEW.sql
-- and not yet synced — so they are what that file produces, byte for byte, rather than a
-- transcription of it. To regenerate after a deliberate catalog change, follow the procedure in
-- 04_rollback_guidance.md.
--
-- The header used to claim these rows were "lifted verbatim" from the seed. They were not: measured
-- 2026-08-02, they matched backend/PEMS.Application/Emails/Common/Assets/email-template-defaults.json
-- on all six text columns for 31 of 31 templates, and differed from the seed on 26 of them. The
-- consequence was the opposite of what this script is for — importing the seed and then running this
-- reported "31 updated" and rewrote the subject, body, name and description of 26 templates to
-- different wording. Regenerating from the seed makes the claim true and the first run a near no-op.
--
-- That divergence is now RESOLVED (2026-08-02, product owner's decision). The shipped defaults
-- email-template-defaults.json hold the authoritative wording; the seed's terser prose was the side
-- that had drifted. The seed was brought up to the JSON on all six text columns for those 26
-- templates, and this file was then regenerated from the updated seed by the procedure above. So the
-- chain is one-directional and single-sourced:
--
--   email-template-defaults.json  →  PEMS_FULL_VS_31_07_NEW.sql  →  this file
--
-- The earlier warning "do not regenerate this file from the JSON" still stands and is not what
-- happened here: this file is still read back out of an imported database, never from the JSON. What
-- changed is the seed it reads from. EmailTemplateDefaultsParityTests asserts the first arrow.
--
-- REGENERATED 2026-08-03 by the section-5 procedure, and this is the drift it repaired. Fourteen of
-- the 31 rows had gone stale against the seed after
-- patches/2026-08-03_email_template_catalog_alignment.sql:
--
--   * 14 templates were missing {{contactInformationBlock}} in body_vi AND body_en (28 fields). The
--     block is what the reply-contact policy renders; running the bundle in that state would have
--     STRIPPED it from all fourteen, and the five whose policy is REQUIRED would then have been
--     unsendable — the renderer refuses a body with nowhere to put a required block.
--   * VISIT_SETUP_PROGRESS_UPDATE still declared variables_text 'hostName,hostEmail'. The canonical
--     wording dropped {{hostEmail}} when the contact block replaced the hand-written contact line, and
--     the renderer compares the declared set against the supplied set in both directions — so a synced
--     database would have failed every send of that template on an undeclared variable.
--   * ACCOUNT_ACTIVATED no longer carries {{actionBlock}}: it has no entry in EmailActionTemplates, and
--     the action block is legal only where an entry exists.
--
-- Nothing here was hand-edited. The rows are the catalog read back out of a database freshly imported
-- from the canonical script, which is what the header above promises they are.
--
-- REGENERATED 2026-08-05 — the reply-contact block is replaced by SENDER VARIABLES. This is the same
-- one-directional chain as before (defaults JSON → canonical seed → this file); what follows records
-- what moved, because the previous state of this file would have UNDONE the migration.
--
--   * the 14 templates carrying {{contactInformationBlock}} in body_vi AND body_en (28 fields) now
--     print a sender signature built from {{senderName}} / {{senderRole}} / {{senderEmail}}. The
--     substitution is textual and local: only the placeholder is swapped, so an operator's own wording
--     around it survives, exactly as patches/2026-08-05_email_sender_variables.sql does it in place.
--   * variables_text on the 28 templates whose capability permits them gained the six {{sender*}}
--     names, taken from the seed row by row rather than recomputed. The three credential-bearing
--     templates (ACCOUNT_EMAIL_CONFIRMATION, AUTH_PASSWORD_RESET_OTP, VISIT_REQUEST_OTP) are
--     deliberately left without them: their whole message is a one-time link, and naming a human
--     sender on one is how a credential mail is made to look forwardable.
--
-- Why this file could not be left as it was: the renderer reads the DECLARED variable list from
-- variables_text, not from the code registry, and refuses any send whose supplied set does not match.
-- Running the OLD version of this script against a migrated database would have rewritten all 28 rows
-- back to their pre-migration bodies and variable lists — restoring {{contactInformationBlock}}, a
-- placeholder nothing renders any more, and dropping the six names the dispatcher now supplies on
-- every send. Every one of those 28 templates would then have failed to send.
--
-- REGENERATED 2026-08-05 (second time that day) — the §16 CONTENT REWRITE. All 31 templates have new
-- subject_vi, body_vi, subject_en and body_en, and nothing else: name, purpose, description and
-- variables_text are byte-identical to the rows above. Every body now follows one structure — greeting,
-- summary table, the facts, the action area, a security note where a credential is involved, the sender
-- card, footer — built entirely from variables each template already declared, so no contract moved.
--
-- Two consequences worth stating, because neither is visible in a diff of this file:
--
--   * this is the channel that delivers the new wording to a DEPLOYED database. The patch
--     patches/2026-08-05_email_sender_variables.sql does NOT: it is a targeted REPLACE that swaps one
--     placeholder and deliberately preserves whatever prose an operator wrote around it. Running only
--     that patch leaves a deployment on the old content, which is correct and intended.
--   * the thirteen templates that DECLARED the six {{sender*}} names while printing none of them now
--     print the sender card. That was a real defect, not a tidy-up: the dispatcher resolved and
--     supplied six values per send that no body read, and the template screen offered an operator six
--     variables that could never appear in the message they were editing.
--
-- VISIT_CONTACT_CLAIM and VISIT_CONTACT_TRANSFER keep the word "contact" and are NOT affected: they
-- are the guest-side PRIMARY CONTACT of a visit request — who the university talks to about a
-- delegation — which has nothing to do with the reply-contact block that was removed.
--
-- What it does, and just as importantly what it does not:
--   * upserts the 31 canonical templates BY template_code — never by numeric
--     email_template_id, so an existing row keeps its id and every sent_emails foreign key
--     pointing at it stays valid;
--   * updates an existing row only where a column actually differs, so re-running does not churn
--     updated_at and does not write rows the binlog will replicate for no reason;
--   * flips the 9 legacy codes of DL-03 to INACTIVE. It does NOT delete them: seeded
--     sent_emails rows may still hold a foreign key to them, and history must stay readable;
--   * leaves every other row alone. A template an operator authored in the admin UI is neither
--     deactivated nor deleted nor rewritten;
--   * never touches sent_emails, sent_email_recipients, sent_email_attachments,
--     email_action_tokens, files, or anything outside email_templates.
--
-- Idempotent: running it twice changes nothing the second time (asserted by 03_verify.sql).
-- =====================================================================

-- ── Connection character set ──────────────────────────────────────────────────────────────────
-- EVERY subject and body below is Vietnamese, and the mysql client on Windows defaults to the
-- console codepage (cp850/cp1252). Without this line the client tells the server "these bytes are
-- cp850", the server transcodes them, and all thirty templates land as mojibake — measured, not
-- assumed: a CLI run against a freshly imported canonical database reported 30 rows "updated" when
-- the correct answer is zero, and left "Tài khoản" stored as "T├ái khoß║ún".
--
-- It hid for a while because the automated suite connects through MySql.Data, which is already
-- UTF-8, and because a snapshot taken through the same mis-configured client compares mangled text
-- to mangled text and finds them equal. The canonical seed script sets the same thing, for the same
-- reason.
SET NAMES utf8mb4;

-- ── Guard: refuse to run anywhere the operator has not named explicitly ────────────────────────
-- Set this on the SAME session before sourcing the file:
--     SET @pems_sync_confirm_database = '<exact database name>';
-- Typing the name is the confirmation. Without it the script stops before writing anything, which
-- is what stands between "I sourced the wrong file in the wrong tab" and a rewritten catalog.
--
-- The variable is SESSION-scoped, and the script clears it again on the way out (last statement).
-- That matters wherever a session outlives one use of it — a connection pool, or a mysql client left
-- open across several files: without the reset, one confirmation would silently authorise every
-- later run on the same connection. Measured, not assumed: before the reset existed, running this
-- script twice on a pooled connection let the second run through with no confirmation at all.
DELIMITER $$
DROP PROCEDURE IF EXISTS pems_email_sync_guard$$
CREATE PROCEDURE pems_email_sync_guard()
BEGIN
  IF DATABASE() IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT =
      'No database selected. USE the target database before sourcing 02_sync_templates.sql.';
  END IF;
  IF @pems_sync_confirm_database IS NULL OR @pems_sync_confirm_database <> DATABASE() THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT =
      'Refusing to sync: set @pems_sync_confirm_database to the exact name of the database you intend to modify.';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.tables
                 WHERE table_schema = DATABASE() AND table_name = 'email_templates') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT =
      'Refusing to sync: email_templates does not exist. Run 01_preflight.sql and read its output.';
  END IF;
END$$
DELIMITER ;
CALL pems_email_sync_guard();
DROP PROCEDURE pems_email_sync_guard;

START TRANSACTION;

-- ── Canonical catalog, staged ─────────────────────────────────────────────────────────────────
DROP TEMPORARY TABLE IF EXISTS _pems_canonical_templates;
CREATE TEMPORARY TABLE _pems_canonical_templates (
  template_code  VARCHAR(100) NOT NULL,
  name           VARCHAR(150) NOT NULL,
  purpose        VARCHAR(100) NOT NULL,
  campus_id      BIGINT UNSIGNED NULL,
  description    VARCHAR(500) NULL,
  status         ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE',
  subject_vi     VARCHAR(255) NULL,
  body_vi        LONGTEXT NULL,
  subject_en     VARCHAR(255) NULL,
  body_en        LONGTEXT NULL,
  body_format    ENUM('PLAIN_TEXT','HTML') NOT NULL DEFAULT 'HTML',
  variables_text VARCHAR(700) NULL,
  created_at     DATETIME NOT NULL,
  PRIMARY KEY (template_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

