   '[PEMS] Confirm you are the contact for visit request {{requestCode}}',
   '<p style="margin:0 0 16px;color:#334155">Dear <strong>{{contactFullName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">You have been recorded as the contact person for a visit request at FPT University. We need you to confirm this role before we continue.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Request code</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{requestCode}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Delegation</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Campus</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Planned time</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{plannedTime}}</td></tr></tbody></table><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Confirmation required</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Open the confirmation page below to accept or decline the contact role. The page asks you to sign in with the Google account of this email address.</p>{{actionBlock}}</div><div style="margin:18px 0;padding:14px 16px;background:#fff7ed;border:1px solid #fed7aa;border-radius:8px;color:#9a3412;line-height:1.6"><strong>Security note:</strong> The link expires and can be used once. Please do not forward this email.</div><div style="margin:20px 