  ('VISIT_PARTICIPANT_INVITATION',
   'Mời nhân sự tham gia hỗ trợ tiếp khách',
   'VISIT_PARTICIPANT', NULL,
   'Email mời nhân sự IC tham gia hỗ trợ một chuyến tiếp khách. Mỗi người nhận có liên kết chấp nhận/từ chối riêng.',
   'ACTIVE',
   '[PEMS] Mời tham gia hỗ trợ tiếp đón đoàn {{delegationName}}',
   '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">{{hostName}} mời bạn tham gia hỗ trợ một chuyến tiếp khách tại {{campusName}}.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Đoàn khách</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Thời gian dự kiến</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedTime}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Cơ sở</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Vai trò của bạn</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{roleLabel}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65"><em>{{hostMessage}}</em></p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Cần bạn phản hồi</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Vui lòng chọn một phương án bên dưới để chúng tôi chốt danh sách nhân sự tham gia.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Invitation to support the visit of {{delegationName}}',
   '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">{{hostName}} invites you to support a visit at {{campusName}}.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Delegation</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Planned time</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedTime}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Campus</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Your role</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{roleLabel}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65"><em>{{hostMessage}}</em></p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Your response is needed</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Please choose one of the options below so we can confirm the supporting team.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmai