"margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Student invitation to support the visit of {{delegationName}}',
   '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">{{hostName}} invites you to help host a visit at {{campusName}}. Taking part is voluntary.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Delegation</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Planned time</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedTime}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Campus</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Your role</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{roleLabel}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65"><em>{{hostMessage}}</em></p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Your response is needed</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Please choose one of the options below. If you accept, the meeting point and detailed instructions will be sent before the day.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'recipientName,delegationName,campusName,plannedTime,hostName,roleLabel,hostMessage,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP),
  ('VISIT_DEPARTMENT_LEADER_INVITATION',
   'Mời phòng ban phối hợp tiếp khách',
   'VISIT_PARTICIPANT', NULL,
   'Email mời Trưởng phòng ban phối hợp tiếp khách; ngoài chấp nhận/từ chối còn có liên kết gán nhân sự yêu cầu đăng nhập.',
   'ACTIVE',
   '[PEMS] Mời phòng ban phối hợp tiếp đón đoàn {{delegationName}}',
   '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">{{hostName}} đề nghị phòng ban của bạn phối hợp cho một chuyến tiếp khách tại {{campusName}}.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Đoàn khách</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Thời gian dự kiến</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedTime}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Cơ sở</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Nội dung phối hợp</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{roleLabel}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65"><em>{{hostMessage}}</em></p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Cần bạn phản hồi</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Vui lòng chọn một phương án bên dưới. Bạn cũng có thể gán trực tiếp một nhân sự của phòng ban để tiếp nhận công việc này.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Request for department support for the visit of {{delegationName}}',
   '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">{{hostName}} asks your department to support a visit at {{campusName}}.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Delegation</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Planned time</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedTime}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Campus</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Support requested</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{roleLabel}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65"><em>{{hostMessage}}</em></p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Your response is needed</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Please choose one of the options below. You can also assign a member of your department to take this on.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'recipientName,delegationName,campusName,plannedTime,hostName,roleLabel,hostMessage,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP),
  ('VISIT_DEPARTMENT_STAFF_ASSIGNMENT',
   'Phân công nhân sự phòng ban hỗ trợ tiếp khách',
   'VISIT_PARTICIPANT', NULL,
   'Gửi cho nhân sự được Trưởng phòng ban gán vào một chuyến tiếp khách. Khác với lời mời: đây là phân công.',
   'ACTIVE',
   '[PEMS] Bạn được phân công hỗ trợ tiếp đón đoàn {{delegationName}}',
   '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Trưởng phòng {{departmentName}} đã phân công bạn hỗ trợ một chuyến tiếp khách tại {{campusName}}.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Đoàn khách</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Thời gian dự kiến</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedTime}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Cơ sở</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Phòng ban</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{departmentName}}</td></tr></tbody></table><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Cần bạn phản hồi</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Vui lòng chọn một phương án bên dưới để phòng ban biết bạn có nhận nhiệm vụ này hay không.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] You have been assigned to support the visit of {{delegationName}}',
   '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">The head of {{departmentName}} has assigned you to support a visit at {{campusName}}.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Delegation</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Planned time</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedTime}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Campus</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Department</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{departmentName}}</td></tr></tbody></table><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Your response is needed</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Please choose one of the options below so your department knows whether you are taking this on.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'recipientName,delegationName,campusName,plannedTime,departmentName,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP),

-- ── VISIT_REMINDER ────────────────────────────────────────────────────────────
  ('VISIT_REMINDER_HOST',
   'Nhắc lịch tiếp khách cho người phụ trách',
   'VISIT_REMINDER', NULL,
   'Nhắc người phụ trách tiếp đón trước giờ tiếp khách theo cấu hình nhắc lịch của chuyến.',
   'ACTIVE',
   '[PEMS] Nhắc lịch tiếp đón đoàn {{delegationName}}',
   '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{hostName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Đây là email nhắc lịch cho chuyến tiếp khách bạn đang phụ trách.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Đoàn khách</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Bắt đầu</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedStart}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Kết thúc</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedEnd}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Cơ sở</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{campusName}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">Trước ngày diễn ra, vui lòng rà soát:</p><ul style="margin:0 0 14px;padding-left:20px;color:#334155;line-height:1.7"><li>Danh sách khách và thành phần phía FPT đã đầy đủ.</li><li>Lịch trình từng mốc thời gian đã được chốt.</li><li>Các hạng mục hậu cần đã được phòng ban xác nhận.</li></ul><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Việc cần làm</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Mở chuyến tiếp khách trong hệ thống để kiểm tra và cập nhật phần còn thiếu.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Reminder: hosting {{delegationName}}',
   '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{hostName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">This is a reminder for the visit you are hosting.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Delegation</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Starts</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedStart}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Ends</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedEnd}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Campus</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{campusName}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">Before the day, please check that:</p><ul style="margin:0 0 14px;padding-left:20px;color:#334155;line-height:1.7"><li>the guest list and the FPT participants are complete;</li><li>every step of the agenda is confirmed;</li><li>the logistics items have been accepted by the departments.</li></ul><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">What to do</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Open the visit in the system to review it and fill in whatever is still missing.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'hostName,delegationName,campusName,plannedStart,plannedEnd,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP),
  ('VISIT_REMINDER_PARTICIPANTS',
   'Nhắc lịch tiếp khách cho người tham gia',
   'VISIT_REMINDER', NULL,
   'Nhắc từng người đã nhận lời mời hoặc được gán, trước giờ tiếp khách. Gửi riêng từng người, không liệt kê người khác.',
   'ACTIVE',
   '[PEMS] Nhắc lịch tham gia tiếp đón đoàn {{delegationName}}',
   '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Đây là email nhắc lịch cho chuyến tiếp khách bạn đã nhận lời tham gia.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Đoàn khách</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Bắt đầu</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedStart}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Kết thúc</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedEnd}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Cơ sở</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{campusName}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">Vui lòng có mặt đúng giờ và mang theo thẻ nhân sự hoặc thẻ sinh viên.</p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Việc cần làm</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Mở chuyến tiếp khách trong hệ thống để xem lịch trình chi tiết và điểm tập trung.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Reminder: supporting the visit of {{delegationName}}',
   '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">This is a reminder for the visit you agreed to support.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Delegation</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Starts</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedStart}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Ends</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedEnd}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Campus</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{campusName}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">Please arrive on time and bring your staff or student card.</p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">What to do</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Open the visit in the system to see the detailed agenda and the meeting point.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'recipientName,delegationName,campusName,plannedStart,plannedEnd,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP),

-- ── LOGISTICS ─────────────────────────────────────────────────────────────────
  ('LOGISTICS_REQUEST_TO_DEPARTMENT',
   'Gửi yêu cầu hậu cần tới phòng ban',
   'LOGISTICS', NULL,
   'Gửi Trưởng phòng ban khi người phụ trách tiếp đón tạo một yêu cầu hậu cần. Có liên kết đồng ý/từ chối dùng một lần.',
   'ACTIVE',
   '[PEMS] Yêu cầu hậu cần: {{logisticsTitle}}',
   '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{departmentLeaderName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">{{requesterName}} gửi tới phòng ban của bạn một yêu cầu hậu cần phục vụ công tác tiếp khách.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Hạng mục</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{logisticsTitle}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Loại</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{logisticsItemType}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Số lượng</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{quantity}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Bắt đầu sử dụng</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{usageStartAt}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Kết thúc sử dụng</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{usageEndAt}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65"><strong>Nội dung chi tiết công việc:</strong> {{logisticsDescription}}</p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Cần bạn phản hồi</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Vui lòng chọn một phương án bên dưới để chúng tôi tiếp tục xử lý. Nếu cần điều chỉnh số lượng hoặc thời gian, hãy chọn thao tác trong hệ thống để gửi đề xuất thay đổi.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Logistics request: {{logisticsTitle}}',
   '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{departmentLeaderName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">{{requesterName}} has sent your department a logistics request for a campus visit.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Item</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{logisticsTitle}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Type</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{logisticsItemType}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Quantity</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{quantity}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Use from</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{usageStartAt}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Use until</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{usageEndAt}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65"><strong>Description:</strong> {{logisticsDescription}}</p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Your response is needed</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Please choose one of the options below so we can proceed. If the quantity or the timing needs to change, use the in-system action to send a counter-proposal.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'departmentLeaderName,requesterName,logisticsTitle,logisticsItemType,quantity,usageStartAt,usageEndAt,logisticsDescription,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP),
  ('LOGISTICS_ASSIGNEE_ASSIGNMENT',
   'Phân công nhân sự xử lý hậu cần',
   'LOGISTICS', NULL,
   'Gửi nhân sự phòng ban khi Trưởng phòng ban phân công họ xử lý một hạng mục hậu cần. Có liên kết nhận/từ chối dùng một lần.',
   'ACTIVE',
   '[PEMS] Bạn được giao hạng mục hậu cần: {{logisticsTitle}}',
   '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{assigneeName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Trưởng phòng đã giao cho bạn một hạng mục hậu cần phục vụ công tác tiếp khách.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Hạng mục</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{logisticsTitle}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Hạn xử lý</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{dueAt}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Đoàn khách</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Cơ sở</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{campusName}}</td></tr></tbody></table><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Cần bạn phản hồi</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Vui lòng chọn một phương án bên dưới để phòng ban biết bạn có nhận hạng mục này hay không.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Logistics task assigned to you: {{logisticsTitle}}',
   '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{assigneeName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Your department head has assigned you a logistics item for a campus visit.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Item</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{logisticsTitle}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Due</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{dueAt}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Delegation</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Campus</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{campusName}}</td></tr></tbody></table><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Your response is needed</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Please choose one of the options below so your department knows whether you are taking this on.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'assigneeName,logisticsTitle,dueAt,campusName,delegationName,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP),
  ('LOGISTICS_CHANGE_PROPOSAL_TO_HOST',
   'Đề xuất thay đổi yêu cầu hậu cần gửi người phụ trách',
   'LOGISTICS', NULL,
   'Gửi người phụ trách tiếp đón khi phòng ban đề xuất thay đổi một yêu cầu hậu cần. Có liên kết chấp nhận/từ chối dùng một lần.',
   'ACTIVE',
   '[PEMS] Đề xuất thay đổi hạng mục hậu cần: {{logisticsTitle}}',
   '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{hostName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Phòng {{departmentName}} đề xuất điều chỉnh một hạng mục hậu cần của đoàn {{delegationName}}.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Hạng mục</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{logisticsTitle}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Số lượng ban đầu</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{originalQuantity}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Số lượng đề xuất</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{proposedQuantity}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Bắt đầu sử dụng đề xuất</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{proposedUsageStartAt}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Kết thúc sử dụng đề xuất</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{proposedUsageEndAt}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65"><strong>Mô tả đề xuất:</strong> {{proposedDescription}}</p><p style="margin:0 0 14px;color:#334155;line-height:1.65"><strong>Lý do đề xuất:</strong> {{proposalNote}}</p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Cần bạn phản hồi</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Vui lòng chọn một phương án bên dưới. Nếu bạn chấp nhận, hạng mục sẽ được cập nhật theo nội dung đề xuất.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Change proposed for logistics item: {{logisticsTitle}}',
   '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{hostName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">{{departmentName}} proposes a change to a logistics item for {{delegationName}}.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Item</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{logisticsTitle}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Original quantity</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{originalQuantity}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Proposed quantity</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{proposedQuantity}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Proposed use from</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{proposedUsageStartAt}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Proposed use until</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{proposedUsageEndAt}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65"><strong>Proposed description:</strong> {{proposedDescription}}</p><p style="margin:0 0 14px;color:#334155;line-height:1.65"><strong>Reason:</strong> {{proposalNote}}</p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Your response is needed</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Please choose one of the options below. If you accept, the item will be updated to match the proposal.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'hostName,logisticsTitle,departmentName,delegationName,originalQuantity,proposedQuantity,proposedUsageStartAt,proposedUsageEndAt,proposedDescription,proposalNote,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP),
  ('LOGISTICS_EXPENSE_REPORT_REMINDER',
   'Nhắc kê khai chi phí hậu cần',
   'LOGISTICS', NULL,
   'Nhắc người phụ trách hạng mục hoàn tất kê khai chi phí sau chuyến tiếp khách.',
   'ACTIVE',
   '[PEMS] Nhắc kê khai chi phí hạng mục: {{itemTitle}}',
   '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Một hạng mục hậu cần bạn phụ trách đã hoàn tất nhưng chưa có kê khai chi phí.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Hạng mục</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{itemTitle}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Hạn kê khai</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{dueAt}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Đoàn khách</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{delegationName}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">Kê khai chi phí là căn cứ để phòng ban tổng hợp quyết toán cho đoàn. Nếu hạng mục không phát sinh chi phí, vui lòng ghi nhận rõ điều đó.</p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Việc cần làm</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Mở biên bản trong hệ thống để kê khai chi phí thực tế của hạng mục này.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Reminder: record the expenses for {{itemTitle}}',
   '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">A logistics item you are responsible for is complete but has no expense record yet.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Item</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{itemTitle}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Due</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{dueAt}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Delegation</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{delegationName}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">The expense record is what the department uses to settle the visit. If the item cost nothing, please record that explicitly.</p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">What to do</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Open the record in the system and enter the actual expenses for this item.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'recipientName,itemTitle,dueAt,delegationName,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP),

-- ── REPORT ────────────────────────────────────────────────────────────────────
  ('REPORT_CAMPUS_OPERATION',
   'Báo cáo vận hành campus',
   'REPORT', NULL,
   'Gửi báo cáo vận hành tiếp khách của một campus kèm tệp PDF đính kèm.',
   'ACTIVE',
   '[PEMS] Báo cáo vận hành cơ sở {{campusName}} kỳ {{periodFrom}} - {{periodTo}}',
   '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Báo cáo vận hành theo cơ sở đã được lập và gửi kèm email này.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Báo cáo</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">Vận hành theo cơ sở</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Cơ sở</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Kỳ báo cáo</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{periodFrom}} - {{periodTo}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">Tệp đính kèm gồm số lượng đoàn đã tiếp đón, tiến độ chuẩn bị và các hạng mục hậu cần trong kỳ.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">Số liệu được kết xuất tại thời điểm gửi email. Nếu dữ liệu trong kỳ được cập nhật sau đó, vui lòng kết xuất lại từ hệ thống.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Campus operation report for {{campusName}}, {{periodFrom}} - {{periodTo}}',
   '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">The campus operation report has been generated and is attached to this email.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Report</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">Campus operation</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Campus</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Period</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{periodFrom}} - {{periodTo}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">The attachment covers the delegations received, preparation progress and logistics items for the period.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">The figures were exported when this email was sent. If the data changes afterwards, please export again from the system.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'recipientName,campusName,periodFrom,periodTo,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP),
  ('REPORT_DEPARTMENT_COLLABORATION',
   'Báo cáo phối hợp tiếp khách của phòng ban',
   'REPORT', NULL,
   'Gửi Trưởng phòng ban báo cáo mức độ phối hợp tiếp khách của phòng ban kèm tệp PDF đính kèm.',
   'ACTIVE',
   '[PEMS] Báo cáo phối hợp phòng {{departmentName}} kỳ {{periodFrom}} - {{periodTo}}',
   '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Báo cáo phối hợp theo phòng ban đã được lập và gửi kèm email này.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Báo cáo</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">Phối hợp theo phòng ban</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Phòng ban</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{departmentName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Kỳ báo cáo</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{periodFrom}} - {{periodTo}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">Tệp đính kèm gồm các yêu cầu hậu cần phòng ban đã tiếp nhận, tỷ lệ chấp nhận và tiến độ hoàn thành trong kỳ.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">Số liệu được kết xuất tại thời điểm gửi email. Nếu dữ liệu trong kỳ được cập nhật sau đó, vui lòng kết xuất lại từ hệ thống.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Department collaboration report for {{departmentName}}, {{periodFrom}} - {{periodTo}}',
   '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">The department collaboration report has been generated and is attached to this email.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Report</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">Department collaboration</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Department</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{departmentName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Period</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{periodFrom}} - {{periodTo}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">The attachment covers the logistics requests the department received, the acceptance rate and completion progress for the period.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">The figures were exported when this email was sent. If the data changes afterwards, please export again from the system.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'recipientName,departmentName,periodFrom,periodTo,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP),
  ('REPORT_DEPARTMENT_INVOICE',
   'Hóa đơn hậu cần tiếp khách của phòng ban',
   'REPORT', NULL,
   'Gửi hóa đơn hậu cần tiếp khách của phòng ban kèm tệp PDF. Dùng chung cho hai chiều gửi: phòng ban gửi lên và campus gửi xuống.',
   'ACTIVE',
   '[PEMS] Bảng kê chi phí phòng {{departmentName}} kỳ {{periodFrom}} - {{periodTo}}',
   '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Bảng kê chi phí theo phòng ban đã được lập và gửi kèm email này.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Báo cáo</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">Bảng kê chi phí</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Phòng ban</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{departmentName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Kỳ báo cáo</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{periodFrom}} - {{periodTo}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">Tệp đính kèm liệt kê từng hạng mục hậu cần đã kê khai chi phí trong kỳ, kèm tổng cộng.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">Bảng kê chỉ gồm các hạng mục đã được kê khai. Hạng mục chưa kê khai sẽ không xuất hiện cho tới khi người phụ trách hoàn tất.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Expense statement for {{departmentName}}, {{periodFrom}} - {{periodTo}}',
   '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">The department expense statement has been generated and is attached to this email.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Report</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">Expense statement</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Department</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{departmentName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Period</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{periodFrom}} - {{periodTo}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">The attachment lists every logistics item with a recorded expense in the period, with a total.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">Only items with a recorded expense appear. An item stays off the statement until whoever is responsible records it.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'recipientName,departmentName,periodFrom,periodTo,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP),
  ('REPORT_PERSONNEL_PERFORMANCE',
   'Báo cáo hiệu suất nhân sự tiếp khách',
   'REPORT', NULL,
   'Gửi từng cá nhân báo cáo hiệu suất tham gia tiếp khách kèm tệp PDF. Phạm vi thống kê do người gửi truyền vào qua scopeLabel.',
   'ACTIVE',
   '[PEMS] Báo cáo nhân sự {{scopeLabel}} - {{personName}} kỳ {{periodFrom}} - {{periodTo}}',
   '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{personName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Báo cáo hoạt động nhân sự đã được lập và gửi kèm email này.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Báo cáo</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">Hoạt động nhân sự</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Phạm vi</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{scopeLabel}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Kỳ báo cáo</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{periodFrom}} - {{periodTo}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">Tệp đính kèm gồm số chuyến tiếp khách đã tham gia, nhiệm vụ được giao và tình trạng hoàn thành trong kỳ.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">Số liệu được kết xuất tại thời điểm gửi email. Nếu dữ liệu trong kỳ được cập nhật sau đó, vui lòng kết xuất lại từ hệ thống.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Personnel report {{scopeLabel}} - {{personName}}, {{periodFrom}} - {{periodTo}}',
   '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{personName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">The personnel activity report has been generated and is attached to this email.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Report</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">Personnel activity</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Scope</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{scopeLabel}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Period</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{periodFrom}} - {{periodTo}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">The attachment covers the visits taken part in, the tasks assigned and their completion status for the period.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">The figures were exported when this email was sent. If the data changes afterwards, please export again from the system.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'personName,scopeLabel,periodFrom,periodTo,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP),
  ('VISIT_SETUP_PROGRESS_UPDATE',
   'Cập nhật công tác chuẩn bị tiếp khách',
   'REPORT', NULL,
   'Người phụ trách tiếp đón gửi bản cập nhật công tác chuẩn bị tới khách và thành phần tham gia, kèm Báo cáo Lịch trình. Không mang liên kết dùng một lần.',
   'ACTIVE',
   '[PEMS] Cập nhật công tác chuẩn bị đón đoàn {{delegationName}}',
   '<p style="margin:0 0 16px;color:#334155">Kính gửi Quý vị,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Chúng tôi xin gửi tới Quý vị thông tin cập nhật về công tác chuẩn bị đón đoàn {{delegationName}} tại {{campusName}}.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Đoàn khách</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Bắt đầu</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedStart}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Kết thúc</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedEnd}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Cơ sở</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Đầu mối phía FPT</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{hostName}}</td></tr></tbody></table>{{setupSummaryBlock}}<p style="margin:0 0 14px;color:#334155;line-height:1.65">Nếu có nội dung nào cần điều chỉnh, xin Quý vị phản hồi trực tiếp email này để chúng tôi cập nhật trước ngày diễn ra.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">Báo cáo Lịch trình đính kèm được tạo từ đúng dữ liệu trong các bảng trên.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Preparation update for the visit of {{delegationName}}',
   '<p style="margin:0 0 16px;color:#334155">Dear Sir or Madam,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Here is an update on the preparations for the visit of {{delegationName}} to {{campusName}}.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Delegation</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Starts</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedStart}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Ends</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedEnd}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Campus</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">FPT contact</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{hostName}}</td></tr></tbody></table>{{setupSummaryBlock}}<p style="margin:0 0 14px;color:#334155;line-height:1.65">If anything needs to change, please reply to this email so we can update it before the day.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">The attached Schedule Report is generated from the same data as the tables above.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'delegationName,campusName,plannedStart,plannedEnd,hostName,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP);

-- The staged catalog must be exactly what we expect before a single production row is touched.
DELIMITER $$
DROP PROCEDURE IF EXISTS pems_email_stage_check$$
CREATE PROCEDURE pems_email_stage_check()
BEGIN
  IF (SELECT COUNT(*) FROM _pems_canonical_templates) <> 31 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT =
      'Staged canonical catalog does not hold the expected number of templates. Aborting.';
  END IF;
  IF EXISTS (SELECT 1 FROM _pems_canonical_templates
             WHERE subject_vi IS NULL OR subject_vi = '' OR body_vi IS NULL OR body_vi = ''
                OR subject_en IS NULL OR subject_en = '' OR body_en IS NULL OR body_en = '') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT =
      'Staged catalog has a template missing VI or EN content. Aborting.';
  END IF;
END$$
DELIMITER ;
CALL pems_email_stage_check();
DROP PROCEDURE pems_email_stage_check;

-- ── 1. Insert canonical templates the target does not have yet ────────────────────────────────
INSERT INTO email_templates
  (template_code, name, purpose, campus_id, description, status,
   subject_vi, body_vi, subject_en, body_en, body_format, variables_text, created_at)
SELECT c.template_code, c.name, c.purpose, c.campus_id, c.description, c.status,
       c.subject_vi, c.body_vi, c.subject_en, c.body_en, c.body_format, c.variables_text, c.created_at
FROM _pems_canonical_templates c
LEFT JOIN email_templates t ON t.template_code = c.template_code
WHERE t.email_template_id IS NULL;

SELECT ROW_COUNT() AS inserted_templates;

-- ── 2. Update the ones that exist, only where something actually differs ──────────────────────
-- Matched on template_code; email_template_id is never written, so foreign keys survive.
-- <=> is the NULL-safe comparison: without it, a row whose description is NULL on both sides would
-- compare UNKNOWN and be rewritten on every run.
UPDATE email_templates t
JOIN _pems_canonical_templates c ON c.template_code = t.template_code
SET t.name           = c.name,
    t.purpose        = c.purpose,
    t.campus_id      = c.campus_id,
    t.description    = c.description,
    t.status         = c.status,
    t.subject_vi     = c.subject_vi,
    t.body_vi        = c.body_vi,
    t.subject_en     = c.subject_en,
    t.body_en        = c.body_en,
    t.body_format    = c.body_format,
    t.variables_text = c.variables_text
WHERE NOT (t.name           <=> c.name
       AND t.purpose        <=> c.purpose
       AND t.campus_id      <=> c.campus_id
       AND t.description    <=> c.description
       AND t.status         <=> c.status
       AND t.subject_vi     <=> c.subject_vi
       AND t.body_vi        <=> c.body_vi
       AND t.subject_en     <=> c.subject_en
       AND t.body_en        <=> c.body_en
       AND t.body_format    <=> c.body_format
       AND t.variables_text <=> c.variables_text);

SELECT ROW_COUNT() AS updated_templates;

-- ── 3. Retire the legacy codes, without deleting them ─────────────────────────────────────────
-- Named one by one on purpose. "Everything not in the canonical set" would also catch templates an
-- operator authored, and there is no column that tells the two apart after the fact.
UPDATE email_templates
SET status = 'INACTIVE'
WHERE status <> 'INACTIVE'
  AND template_code IN ('ACCOUNT_CREATED_INTERNAL', 'VISIT_REQUEST_APPROVED', 'VISIT_REQUEST_REJECTED', 'VISIT_CANCELLED', 'HOST_ASSIGNMENT', 'VISIT_REQUEST_SUBMITTED_NOTIFY', 'LOGISTICS_REQUEST', 'LOGISTICS_REQUEST_SUBMITTED_NOTIFY', 'OTP_VISIT_REQUEST');

SELECT ROW_COUNT() AS deactivated_legacy_templates;

DROP TEMPORARY TABLE IF EXISTS _pems_canonical_templates;

COMMIT;

SELECT 'sync complete' AS result, DATABASE() AS db, NOW() AS finished_at;

-- Spend the confirmation. The next run on this session must name its target again.
SET @pems_sync_confirm_database = NULL;
